"""Manifest pipeline operator page; all dynamic values use textContent."""
PAGE = """<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>UART pipeline</title></head><body>
<h1>UART: кампании и анализ</h1><p>Кандидаты не являются подтверждёнными ошибками. Перед запуском проверьте физический стенд.</p>
<input id="token" type="password" autocomplete="off" placeholder="Токен"><button id="login">Войти</button><button id="logout">Выйти</button><p id="error" role="status"></p>
<section><h2>Управление</h2><pre id="configured"></pre><p id="progress"></p><button id="start">Новая кампания</button><button id="stop">Остановить USB-попытки</button><button id="resume">Продолжить выбранную</button></section>
<section><h2>Предпроверка и UART</h2><pre id="preflight"></pre><pre id="uart"></pre><h3>Выбранные устройства</h3><pre id="selection"></pre></section>
<section><h2>История и результаты</h2><select id="campaign"></select><button id="refresh">Обновить</button><p id="analysis-state"></p><div id="attempts"></div><div id="pipeline"></div></section>
<section><h2>Артефакты</h2><div id="downloads"></div></section><script src="/pipeline.js"></script><script src="/uart-review.js"></script></body></html>""".encode('utf-8')
SCRIPT = """'use strict';
const names={idle:'Ожидание',preparing:'Выбор корпуса и предпроверка',running:'USB-попытки',stopping:'Остановка USB',analyzing:'Анализ остановленного захвата',completed:'Кампания и анализ завершены',stopped:'Остановлена',failed:'Ошибка — проверьте диагностику'};const el=id=>document.getElementById(id);let token='',epoch=0,abort=new AbortController(),busy=false;
function node(tag,value){const n=document.createElement(tag);n.textContent=String(value);return n;}
async function api(path,body){const generation=epoch,options={signal:abort.signal,headers:{Authorization:'Bearer '+token}};if(body!==undefined){options.method='POST';options.headers['Content-Type']='application/json';options.body=JSON.stringify(body);}const r=await fetch(path,options),data=await r.json();if(generation!==epoch)throw new Error('Stale session');if(!r.ok)throw new Error(data.error||'Request failed');return data;}
async function file(campaign,area,name){const generation=epoch;try{const r=await fetch('/api/file?'+new URLSearchParams({campaign,area,name}),{signal:abort.signal,headers:{Authorization:'Bearer '+token}});if(!r.ok)throw new Error((await r.json()).error);const blob=await r.blob();if(generation!==epoch)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=campaign+'-'+area+'-'+name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){if(generation===epoch&&e.name!=='AbortError')el('error').textContent=e.message;}}
function download(campaign,area,name){const b=node('button',name);b.onclick=()=>file(campaign,area,name);el('downloads').append(b);}
async function refresh(){if(!token||busy)return;busy=true;const generation=epoch;try{const s=await api('/api/state');el('configured').textContent=JSON.stringify(s.configured,null,2);el('progress').textContent=(names[s.stage]||s.stage)+' · сохранённый прогресс '+s.completed+' / '+s.configured.iterations;el('preflight').textContent=JSON.stringify(s.preflight,null,2);el('uart').textContent=JSON.stringify(s.uart,null,2);el('selection').textContent=JSON.stringify(s.selection,null,2);el('error').textContent=s.execution_error||s.analysis_error||'';const active=s.active;el('start').disabled=s.busy;el('resume').disabled=s.busy;el('stop').disabled=!s.busy||s.stage==='analyzing';const rows=await api('/api/campaigns'),keep=el('campaign').value||active||rows[0]?.id||'';window.rows=rows;el('campaign').replaceChildren();for(const row of rows){const o=node('option',new Date(row.modified_ns/1000000).toLocaleString('ru-RU')+' · попыток '+row.attempts.length+' · '+row.id.slice(0,8));o.value=row.id;el('campaign').append(o);}el('campaign').value=keep;if(keep){const d=await api('/api/details?'+new URLSearchParams({campaign:keep}));el('analysis-state').textContent=d.state;el('attempts').replaceChildren();for(const row of d.attempts){const a=node('article',row.attempt_id+' · '+(!row.result?'Полный результат ещё не сохранён':row.result.infrastructure_error|| (row.result.interrupted?'Прервана':row.result.window_completed?'Окно исполнителя выполнено':'Окно исполнителя не завершено')));a.append(node('pre',JSON.stringify(row.result,null,2)));el('attempts').append(a);}el('pipeline').replaceChildren();el('downloads').replaceChildren();for(const p of d.pipelines){el('pipeline').append(node('h3',p.name),node('pre',JSON.stringify(p.summary||p.error,null,2)));for(const r of p.reports){const card=node('article','Сообщение ядра — кандидат для проверки'+(r.display_truncated?' · показан ограниченный текст':''));card.append(node('pre',r.context||''),node('pre',r.text||r.display_error||''),node('pre',JSON.stringify(r.associations||[],null,2)));el('pipeline').append(card);}for(const d of p.diagnostics)el('pipeline').append(node('article',d.kind+' · '+(d.attempt||'канал')),node('pre',d.text));for(const name of p.files)download(keep,p.name,name);}for(const name of ['campaign.json','checkpoint.json'])download(keep,'campaign',name);for(const row of d.attempts)for(const name of ['config.json','started.json','window.json','result.json','executor.log'])download(keep,row.attempt_id,name);for(const name of ['uart.raw','chunks.jsonl','events.jsonl'])download(keep,'capture',name);}}catch(e){if(generation===epoch&&e.name!=='AbortError')el('error').textContent=e.message;}finally{if(generation===epoch)busy=false;}}
async function command(action){if(!token)return;if(action!=='stop'&&!confirm('Запустить USB-активность на выделенном стенде?'))return;try{await api('/api/'+action,action==='resume'?{campaign:el('campaign').value}:{});await refresh();}catch(e){el('error').textContent=e.message;}}
el('login').onclick=()=>{token=el('token').value;el('token').value='';refresh();};el('logout').onclick=()=>{epoch++;abort.abort();abort=new AbortController();token='';busy=false;window.rows=[];for(const id of ['configured','progress','preflight','uart','selection','error','analysis-state'])el(id).textContent='';for(const id of ['campaign','attempts','pipeline','downloads'])el(id).replaceChildren();};for(const action of ['start','stop','resume'])el(action).onclick=()=>command(action);el('refresh').onclick=refresh;el('campaign').addEventListener('change',refresh);setInterval(refresh,3000);
""".encode('utf-8')
